  [data-slot="search"] [data-part="search.filter"][data-label]::before { content: attr(data-label); position: absolute; left: 4px; bottom: calc(100% + 4px); font-size: 18px; line-height: 28px; font-weight: 600; color: #fff; white-space: nowrap; pointer-events: none; }
