}
[data-slot="search"] [data-part="search.filters"] [data-part="search.field"], [data-slot="search"] [data-part="search.filter"] { height: 40px; border: 1px solid transparent !important; border-radius: 10px !important; background: #18181b !important; color: #d1d5dc !important; font-size: 14px !important; line-height: 20px !important; font-weight: 500 !important; }
