@media (min-width: 641px) { [data-part="search.grid"][data-variant="grid"] { grid-template-columns: repeat(auto-fill, 178px) !important; gap: 16px !important; } }

/* ── Phones: the hero runs under a transparent app bar, its copy centred; 16 px gutters; 20 px headings. ── */
